window.AponarQuartet2Data={"q2":{"chapters.theme_bn":{"প্রসঙ্গ, পরোক্ষ কথা ও ভাষার সূক্ষ্ম পার্থক্য":"السياق والكلام غير المباشر والفروق الدقيقة في اللغة","যুক্তি, বিকল্প দৃষ্টিকোণ ও মতামত গঠন":"المنطق ووجهة النظر البديلة وتكوين الرأي","অভিজ্ঞতা থেকে শেখা ও ভদ্রভাবে মতের পার্থক্য বলা":"التعلم من التجربة والتعبير بأدب عن اختلاف الرأي","কাজের মূল্যবোধ, সাক্ষাৎকার নেওয়া ও তথ্য সাজানো":"قيم العمل وإجراء المقابلات وتنظيم المعلومات","ঘটনার মোড়, উপমা ও অনুভূতির পরিবর্তন পড়া":"قراءة نقاط التحول والاستعارات وتحولات المشاعر","তুলনা, পরিবর্তনের প্রবণতা ও সীমিত সিদ্ধান্ত":"المقارنة واتجاه التغير والقرار المحدود"},"chapters.title_bn":{"অধ্যায় ৮ · পেশাদারিত্ব ও সাক্ষাৎকার":"الفصل 8 · الاحترافية والمقابلات","অধ্যায় ১০ · তথ্য দিয়ে সমাজ বোঝা":"الفصل 10 · فهم المجتمع من خلال البيانات","অধ্যায় ৯ · গল্প, অনুভূতি ও পর্যালোচনা":"الفصل 9 · القصص والمشاعر والمراجعات","অধ্যায় ১২ · চিন্তার পরিবর্তন ও সমাজ":"الفصل 12 · تغير الأفكار والمجتمع","অধ্যায় ১১ · শব্দের আড়ালের অর্থ":"الفصل 11 · المعاني الخفية وراء الكلمات","অধ্যায় ৭ · ভিন্ন সংস্কৃতি, নতুন উপলব্ধি":"الفصل 7 · ثقافات مختلفة وإدراكات جديدة"},"form_guide.label":{"সম্ভাব্য রূপ":"صيغة الإمكان","い-বিশেষণ":"صفة い","な-বিশেষণ":"صفة な","ইচ্ছার রূপ":"صيغة الإرادة"},"form_guide.meaning_bn":{"বর্তমান বা ভবিষ্যতের সাধারণ নেতিবাচক রূপ।":"الصيغة المنفية العامة للحاضر أو المستقبل.","ます・です ছাড়া সাধারণ রূপ: বর্তমান, অতীত, ইতিবাচক ও নেতিবাচক। N ও な-বিশেষণের だ কখন বাদ/な/の হবে তা প্রতিটি নিয়মে দেওয়া আছে।":"الصيغ العادية غير ます/です: الحاضر والماضي والإثبات والنفي. ومتى يُحذف だ أو يُستخدم な/の مع الأسماء وصفات な مشروح في كل قاعدة.","বিশেষ্যকে বর্ণনা করলে な লাগে। সব গঠনে な থাকবে না; পাঠের সংযোগ দেখুন।":"يلزم な عند وصف اسم. ولا يوجد な في كل التراكيب؛ راجع اتصالات الدرس.","সাধারণ অতীত রূপ।":"صيغة الماضي العامة.","ます-রূপ থেকে শুধু ます বাদ দিন।":"احذف ます فقط من صيغة ます.","“করি/করব” ধরনের volitional form।":"صيغة إرادة من نوع «أفعل / سأفعل».","ক্রিয়ার সংযোগের て-form; কোথাও で হয়।":"صيغة て لتصريف الفعل؛ وأحيانا تصبح で.","কোনো কাজ করতে পারা বোঝায়।":"تعبر عن القدرة على فعل شيء.","বিশেষ্য: ব্যক্তি, বস্তু বা বিষয়ের নাম।":"الاسم: اسم شخص أو شيء أو موضوع.","い-বিশেষণ, যেমন বড়, দামি। নেতিবাচক ও অতীতে রূপ বদলায়।":"صفة い، مثل كبير وغال. تتغير صيغتها في النفي والماضي.","ক্রিয়ার dictionary form; এর মানে সব ক্রিয়া る দিয়ে শেষ হবে না।":"الصيغة المعجمية للأفعال؛ وهذا يعني أن ليست كل الأفعال تنتهي بـ る.","শর্তের ば-form।":"صيغة الشرط ば."},"lessons.examples.bangla":{"সংস্কৃতি আলাদা বলেই আলোচনা করা জরুরি।":"لأن الثقافات مختلفة تحديدا، فالنقاش ضروري.","তিনি শিক্ষক বলার চেয়ে বরং বন্ধুর মতো।":"بدلا من القول إنه معلم، فهو أشبه بصديق.","আগামীকাল হলে সাহায্য করা একেবারে অসম্ভব নয়।":"إذا كان الأمر غدا، فالمساعدة ليست مستحيلة تماما.","বয়স বাড়ার সঙ্গে চিন্তার ধরনও বদলায়।":"مع ازدياد العمر، تتغير طريقة التفكير أيضا.","শিশুটি কাঁদল মনে হতেই সঙ্গে সঙ্গে হাসল।":"في اللحظة التي ظننت فيها أن الطفل يبكي، ابتسم على الفور.","বিস্তৃত এলাকাজুড়ে জরিপ প্রয়োজন।":"يلزم إجراء استطلاع على منطقة واسعة.","খাবারটি যে খেতে পারি না তা নয়, তবে একটু ঝাল।":"ليس الأمر أنني لا أستطيع أكل الطعام، لكنه حار قليلا.","গত বছরের তুলনায় ব্যবহারকারী বেড়েছে।":"ازداد المستخدمون مقارنة بالعام الماضي.","বসন্ত হলেও সকালে এখনো ঠান্ডা।":"رغم أنه الربيع، ما زال الجو باردا في الصباح.","যান বা না যান, জানাবেন।":"سواء ذهبت أم لم تذهب، أخبرنا من فضلك.","এভাবে চললে দুর্ঘটনার আশঙ্কা আছে।":"إذا استمرت الأمور هكذا، فهناك خطر وقوع حادث.","বাইরে বের হওয়া মাত্রই বৃষ্টি শুরু হলো।":"بمجرد أن خرجت، بدأ المطر.","বন্ধুর সঙ্গে দেখা হওয়ার সূত্রে আমার চিন্তা বদলেছে।":"تغيرت أفكاري بمناسبة لقاء صديقي.","না করলেও ভদ্রভাবে জানানো ভালো।":"حتى لو لم تفعل ذلك، فمن الأدب أن تخبرهم.","টোকিওর তুলনায় এই শহরে ভাড়া কম।":"الإيجار أرخص في هذه المدينة مقارنة بطوكيو.","এইমাত্র বেরিয়েছে, তাই ইতিমধ্যে পৌঁছে যাওয়ার কথা নয়।":"لقد غادر للتو، فلا يمكن أن يكون قد وصل بالفعل.","বিষয়বস্তু যাচাই করার পরে স্বাক্ষর করুন।":"وقّع من فضلك بعد التحقق من المحتويات.","জাপানিতে অভ্যস্ত হওয়ার সঙ্গে কথা বলা আনন্দদায়ক হয়েছে।":"مع اعتيادي على اليابانية، أصبح التحدث بها ممتعا.","কথা দিয়েছি বলে এখন আর না করা চলে না।":"بما أنني وعدت، لا أستطيع التراجع الآن.","এই প্রস্তাব সম্পর্কে আমার প্রশ্ন আছে।":"لدي سؤال حول هذا الاقتراح.","মতবিনিময় অনুষ্ঠানকে উপলক্ষ করে স্থানীয় কাজে যুক্ত হয়েছি।":"باتخاذ اجتماع تبادل الآراء مناسبة، انخرطت في العمل المحلي.","ট্রেন বন্ধ হওয়ায় ট্যাক্সি নেওয়া ছাড়া উপায় ছিল না।":"بما أن القطارات توقفت، لم يكن لدي خيار سوى ركوب سيارة أجرة.","তিনি হাল না ছেড়ে অনুশীলন চালিয়েছেন।":"واصل التدريب دون أن يستسلم.","মনে হচ্ছিল যেন স্বপ্ন দেখছি।":"شعرت وكأنني أحلم.","অতিথির চাহিদা অনুযায়ী কক্ষের ব্যবস্থা করব।":"سنرتب الغرفة وفقا لطلبات الضيف.","প্রিয় বন্ধু বলেই সৎভাবে জানাতে চাই।":"لأنك صديق عزيز تحديدا، أريد أن أخبرك بصراحة.","প্রতিদিন অনুশীলন করছে, নিশ্চয়ই দক্ষ হবে বলে মনে করি।":"إنهم يتدربون كل يوم، لذا أظن أنهم سيصبحون مهرة بالتأكيد.","ব্যাখ্যা পড়েছি ঠিকই, কিন্তু ব্যবহারের পদ্ধতি এখনো বুঝিনি।":"قرأت الشرح، لكنني ما زلت لا أفهم كيفية استخدامه.","দোকানটি সারা বছর খোলা থাকে।":"المتجر مفتوح طوال العام.","এত সহজ উপায়ে সব মনে রাখা যাবে, এমন নয় মোটেও।":"ليس الأمر بأي حال أنك تستطيع تذكر كل شيء بمثل هذه الطريقة السهلة.","শুধু বিদেশি শিক্ষার্থী নয়, এলাকার মানুষও অংশ নিতে পারেন।":"ليس الطلاب الأجانب فقط، بل يمكن لأهل المنطقة أيضا المشاركة.","আমার জানা মতে দোকানটি রবিবারও খোলা থাকে।":"حسب علمي، المتجر مفتوح أيام الأحد أيضا.","ব্যবস্থার পরিবর্তনের সঙ্গে প্রক্রিয়াও বদলেছে।":"مع تغير النظام، تغيرت العملية أيضا.","টাইফুনের কারণে ট্রেন বন্ধ হওয়ার আশঙ্কা আছে।":"هناك خشية من توقف القطارات بسبب الإعصار.","তিনি পথঘাট ভালো জানেন, নিশ্চয়ই স্থানীয় বলে মনে হয়।":"إنه يعرف الطرق جيدا، لذا يبدو بالتأكيد أنه من أهل المنطقة.","জ্বর আছে বলে বিশ্রাম না নিয়ে থাকা চলে না।":"لدي حمى، فلا أستطيع ألا أرتاح.","মতবিনিময় অনুষ্ঠানের মাধ্যমে নতুন বন্ধু হয়েছে।":"كوّنت أصدقاء جددا من خلال برنامج التبادل.","সুস্থ থাকা পর্যন্ত কাজ চালিয়ে যেতে চাই।":"أريد أن أواصل العمل ما دمت بصحة جيدة.","সফল হব কি না তা প্রস্তুতির ওপর নির্ভর করে।":"نجاحي من عدمه يعتمد على استعدادي.","আকাশ অন্ধকার হলো মনে হতেই প্রবল বৃষ্টি নামল।":"في اللحظة التي ظننت فيها أن السماء أظلمت، بدأ مطر غزير يهطل.","বড় ভাই সকালে স্বচ্ছন্দ, এর বিপরীতে ছোট ভাই রাতে স্বচ্ছন্দ।":"الأخ الأكبر مرتاح في الصباح، بينما الأخ الأصغر مرتاح في الليل.","ছোটবেলায় নদীতে প্রায়ই খেলতাম।":"عندما كنت صغيرا، كنت ألعب في النهر كثيرا.","এটি বাস্তব অভিজ্ঞতার ভিত্তিতে লেখা প্রতিবেদন।":"هذا تقرير مكتوب بناء على تجربة حقيقية.","বিদেশের জীবন আনন্দের, আবার পরিবারের জন্য মনও খারাপ হয়।":"الحياة في الخارج ممتعة، لكنني أفتقد عائلتي أيضا.","অংশ নিন বা না নিন, উত্তর দিন।":"سواء شاركت أم لم تشارك، أجب من فضلك.","এই সমস্যা শুধু জাপানে নয়, অন্য দেশেও আছে।":"هذه المشكلة ليست في اليابان فقط، بل في بلدان أخرى أيضا.","কক্ষটি শান্ত বলার চেয়ে বরং নির্জন লাগে।":"بدلا من القول إن الغرفة هادئة، تبدو مهجورة.","তিন দিনজুড়ে প্রশিক্ষণ অনুষ্ঠিত হয়েছে।":"أُقيم التدريب على مدى ثلاثة أيام.","শহর একদিকে সুবিধাজনক, অন্যদিকে জীবনযাত্রার খরচ বেশি।":"المدينة مريحة من جهة، لكن تكلفة المعيشة مرتفعة من جهة أخرى.","কারণ না জেনে বিচার করা উচিত নয়।":"لا ينبغي أن تحكم دون معرفة السبب.","জাপানি হলেও সবাই যে কানজিতে দক্ষ তা নয়।":"كون الشخص يابانيا لا يعني أنه يجيد الكانجي.","গ্রাহকসেবার ক্ষেত্রে অন্যের কথা শোনা জরুরি।":"في خدمة العملاء، الاستماع إلى الآخرين أمر أساسي.","জাপানি বলতে পারলেও সম্মানসূচক ভাষায় আত্মবিশ্বাস নেই।":"رغم أنني أستطيع التحدث باليابانية، تنقصني الثقة في لغة الاحترام.","কণ্ঠস্বর শোনা মাত্রই স্বস্তি পেলাম।":"في اللحظة التي سمعت فيها ذلك الصوت، شعرت بالارتياح.","অভিজ্ঞতার সঙ্গে মানানসই কাজের দায়িত্ব দেব।":"سأكلفهم بمسؤوليات عمل تناسب خبرتهم.","আগে বন্ধুদের সঙ্গে প্রায়ই দীর্ঘ চিঠি লিখতাম।":"في الماضي، كنت أكتب رسائل طويلة إلى أصدقائي كثيرا.","সুবিধা বেড়েছে ঠিকই, তবু সমস্যা রয়ে গেছে।":"صحيح أن الراحة ازدادت، لكن المشاكل باقية.","জরিপের ফলকে ভিত্তি করে পরিকল্পনা করেছি।":"وضعنا الخطة بناء على نتائج الاستطلاع.","চালিয়ে যেতে পেরেছি ঠিক সহকর্মীরা পাশে ছিলেন বলেই।":"تمكنت من الاستمرار تحديدا لأن زملائي وقفوا بجانبي.","তিনি এমনভাবে কথা বললেন যেন কিছুই জানেন না।":"تحدث وكأنه لا يعرف شيئا عن الأمر.","বন্ধুর জন্য চিন্তায় যোগাযোগ না করে থাকতে পারিনি।":"لقلقي على صديقي، لم أستطع إلا أن أتواصل معه.","দামি জিনিস সবসময় ভালো হবে এমন নয়।":"الأشياء الغالية ليست جيدة دائما.","সহযোগিতা হলো একই লক্ষ্যে একসঙ্গে কাজ করা।":"التعاون يعني العمل معا نحو الهدف نفسه.","প্রবল বৃষ্টিতে পরিকল্পনা বদলানো ছাড়া উপায় নেই।":"مع المطر الغزير، لا خيار لدينا سوى تغيير خططنا.","সূচি ঠিক হওয়া মাত্র জানাব।":"سأخبرك بمجرد أن يُحسم الجدول.","বয়স নির্বিশেষে যে কেউ অংশ নিতে পারেন।":"يمكن لأي شخص المشاركة بغض النظر عن العمر.","কেইগো বলতে অন্যের প্রতি সম্মান প্রকাশের ভাষা বোঝায়।":"تشير الكيغو إلى اللغة المستخدمة للتعبير عن الاحترام للآخرين.","জনসংখ্যা বৃদ্ধির সঙ্গে আবাসনের প্রয়োজন বেড়েছে।":"مع ازدياد السكان، ازدادت الحاجة إلى السكن.","আমি শুধু মতামত জানিয়েছি।":"لقد ذكرت رأيي فحسب.","এবারের সাফল্য আপনাদের পরিশ্রমের ফলই।":"هذا النجاح ليس سوى نتيجة عملكم الجاد.","ঘটনাটি শুনলে না হেসে থাকতে পারি না।":"عندما سمعت القصة، لم أستطع إلا أن أضحك.","এটি কেবল একটি উদাহরণ।":"هذا مجرد مثال."},"lessons.explanation_bn":{"বক্তার দেখা দুটি ঘটনা খুব দ্রুত বদলে যায়। প্রথম অবস্থা বুঝে ওঠার আগেই পরের অবস্থা আসে—এই পরিবর্তনকে তুলে ধরে।":"الحدثان اللذان يلاحظهما المتحدث يتغيران بسرعة كبيرة. يبرز هذا التغير السريع حيث تصل الحالة التالية قبل أن تُفهم الحالة الأولى تماما.","একটি ঘটনা বড় পরিবর্তন, নতুন অভ্যাস বা সম্পর্কের সূচনা করে। শুধু যেকোনো কারণ নয়, শুরু হওয়ার উপলক্ষকে জোর দেয়।":"حدث يبدأ تغيرا كبيرا أو عادة جديدة أو علاقة. يؤكد مناسبة البداية، لا أي سبب فحسب.","কাজটি করতে সক্ষম হলেও দায়িত্ব, প্রতিশ্রুতি বা সামাজিক কারণে তা করা গ্রহণযোগ্য নয়। নেতিবাচক ক্রিয়ার সঙ্গে “না করে থাকা চলে না”, অর্থাৎ করতেই হবে।":"حتى لو كان المرء قادرا على فعل العمل، فليس مقبولا فعله بسبب المسؤولية أو الوعد أو أسباب اجتماعية. ومع الأفعال المنفية، يعني «لا أستطيع ألا أفعله»، أي يجب فعله.","কোনো শব্দ বা ধারণাকে সামনে এনে তার অর্থ, সংজ্ঞা বা মূল বৈশিষ্ট্য ব্যাখ্যা করুন। প্রবন্ধ ও ব্যাখ্যামূলক লেখায় মানায়।":"قدّم كلمة أو مفهوما واشرح معناه أو تعريفه أو خصائصه الرئيسية. مناسب للمقالات والكتابات الشرحية.","পরিমাণ, ভূমিকা বা গুরুত্বকে সীমিত করে বোঝায়। বক্তা মনে করেন বিষয়টিকে তার চেয়ে বড় করে দেখা ঠিক নয়।":"يحد من الكمية أو الدور أو الأهمية. يشعر المتحدث أنه ليس من الصواب رؤية الأمر أكبر من ذلك.","Vた-এর সঙ্গে প্রথম কাজ ভালোভাবে করে তারপর সিদ্ধান্ত বা কাজ করুন। Vる-এর সঙ্গে কোনো কাজের ক্ষেত্রে কী গুরুত্বপূর্ণ তা ব্যাখ্যা করুন।":"مع Vた، أكمل الفعل الأول بشكل صحيح قبل أن تقرر أو تتصرف. ومع Vる، اشرح ما هو مهم عند القيام بفعل معين.","বাস্তবে ঠিক সেই অবস্থা না হলেও তেমন দেখায় বা অনুভূত হয়। কল্পনা ও উপমা তৈরি করতে ব্যবহার করুন।":"حتى لو لم يكن الأمر كذلك تماما في الواقع، يبدو أو يُشعر به هكذا. استخدمه لخلق الخيال والتشبيهات.","পরিচয় বা আসল কারণকে জোর দিয়ে নির্দিষ্ট করে। বক্তা দৃঢ়ভাবে বলেন, এটিই আসল ব্যাখ্যা। আনুষ্ঠানিক যুক্তি বা মূল্যায়নে উপযোগী।":"يحدد بتأكيد هوية أو السبب الحقيقي. يؤكد المتحدث بحزم أن هذا هو التفسير الحقيقي. مفيد في الاستدلال الرسمي أو التقييم.","চাহিদা, ক্ষমতা, পরিস্থিতি বা পরিবর্তনের সঙ্গে সামঞ্জস্য রেখে কাজ বা ব্যবস্থা বদলায়। সবার জন্য একই ব্যবস্থা বোঝায় না।":"تتغير الأفعال أو الترتيبات لتتكيف مع المطالب أو القدرات أو المواقف أو التغيرات. ولا يعني الترتيب نفسه للجميع.","একই বিষয় বা পরিস্থিতির দুটি ভিন্ন দিক পাশাপাশি তুলে ধরে। ভালো-মন্দ, সুবিধা-অসুবিধা বা পরস্পর ভিন্ন প্রবণতা তুলনা করা যায়।":"يعرض جانبين مختلفين من القضية أو الموقف نفسه جنبا إلى جنب. يمكن مقارنة الجيد والسيئ، أو المزايا والعيوب، أو الاتجاهات المختلفة المتبادلة.","একটি বড় পরিবর্তন বা ঘটনার সঙ্গে সম্পর্কিত আরেকটি পরিবর্তন ঘটে। সামাজিক প্রবণতা, নীতি ও সংখ্যা ব্যাখ্যায় উপযোগী।":"يحدث تغير آخر مرتبط بتغير أو حدث كبير. مفيد في شرح الاتجاهات الاجتماعية والسياسات والأرقام.","আগের অবস্থা বা শর্ত বজায় থাকা পর্যন্ত পরের কথা সত্য। 知[し]っている限[かぎ]り বলতে নিজের জানার সীমার মধ্যেও বোঝায়।":"ما دامت الحالة أو الشرط السابق مستمرا، فما يلي صحيح. وتعني 知[し]っている限[かぎ]り أيضا في حدود ما يعرفه المرء.","কারণ বা পরিস্থিতি বিবেচনা করে বক্তা প্রবলভাবে সম্ভাবনা অস্বীকার করেন। এটি বক্তার দৃঢ় বিচার; বৈজ্ঞানিক নিশ্চয়তা দাবি নয়।":"بالنظر إلى السبب أو الموقف، ينكر المتحدث الاحتمال بقوة. هذا هو حكم المتحدث الحازم؛ ولا يدعي يقينا علميا.","নিয়ম, তথ্য, গবেষণা বা অভিজ্ঞতাকে সিদ্ধান্তের ভিত্তি হিসেবে ব্যবহার করা হয়। অনুমানের বদলে কী ভিত্তির ওপর কাজ হয়েছে তা বলুন।":"تُستخدم القواعد أو المعلومات أو البحث أو التجربة أساسا للقرار. بدلا من التخمين، اذكر الأساس الذي بُني عليه العمل.","কাজ বা অবস্থা দীর্ঘ সময়, বিস্তৃত এলাকা বা বহু বিষয়ের পরিসরজুড়ে চলেছে বোঝায়। পরিসরের বিস্তারকে গুরুত্ব দেয়।":"يشير إلى أن فعلا أو حالة تستمر على مدى فترة طويلة أو منطقة شاسعة أو مجموعة واسعة من الموضوعات. يؤكد مدى النطاق.","অন্য বিকল্প না থাকায় অনিচ্ছা সত্ত্বেও কাজটি করতে হয়। বাইরের পরিস্থিতি বা বাস্তব সীমাবদ্ধতা বক্তাকে বাধ্য করে।":"بما أنه لا توجد بدائل أخرى، يضطر المرء إلى القيام بالمهمة رغم التردد. الظروف الخارجية أو القيود العملية تجبر المتحدث.","আবেগ বা প্রবল স্বাভাবিক তাড়নায় কাজটি না করে থাকা যায় না। নিজের অনুভূতি বা সহজে বোঝা প্রতিক্রিয়া প্রকাশে মানায়।":"مدفوعا بمشاعر أو دوافع طبيعية قوية، لا تستطيع إلا أن تفعل شيئا. مناسب للتعبير عن مشاعر المرء أو ردود فعل سهلة الفهم.","একটি শ্রেণির বাইরে একই কথা আরও বিস্তৃত শ্রেণিতেও প্রযোজ্য হলে ব্যবহার করুন। পরে も বা 広[ひろ]く-এর মতো বিস্তারের ইঙ্গিত থাকতে পারে।":"استخدم هذا عندما ينطبق الشيء نفسه ليس على فئة واحدة فقط بل على فئة أوسع تتجاوزها أيضا. لاحقا في الجملة قد يكون هناك تلميح إلى التوسع مثل も أو 広[ひろ]く.","আগের তথ্য স্বীকার করেও সীমাবদ্ধতা, ব্যতিক্রম বা সতর্কতা জানান। প্রথম কথাটি মিথ্যা না বলে তাকে শর্তসাপেক্ষ করেন।":"الإقرار بالمعلومات السابقة مع ذكر قيد أو استثناء أو تحذير. يجعل العبارة الأولى مشروطة دون أن يسميها كاذبة.","আগের কাজ ঘটার সঙ্গে সঙ্গেই অপ্রত্যাশিত পরিবর্তন বা ঘটনা ঘটে। পরের অংশে সাধারণত পরিকল্পিত নির্দেশ বা ইচ্ছা থাকে না।":"يحدث تغير أو حدث غير متوقع مباشرة بعد الفعل السابق. النصف الثاني عادة لا يحتوي على أوامر أو رغبات مقصودة.","লক্ষণ, পরিস্থিতি বা জানা তথ্য থেকে বক্তা শক্ত অনুমান করেন। সরাসরি দেখা প্রমাণিত ঘটনা বলার বদলে নিজের বিচার প্রকাশ পায়।":"يقوم المتحدث بتخمين قوي بناء على علامات أو مواقف أو معلومات معروفة. بدلا من ذكر حقائق مثبتة لوحظت مباشرة، يعبر عن حكمه الخاص.","ক্রিয়ার ます বাদ দেওয়া রূপে কোনো কাজ শেষ হলে দ্রুত পরের কাজ করার পরিকল্পনা জানায়। বিশেষ্যের সঙ্গে ফল নির্ভর করার অর্থ হয়।":"يشير إلى خطة للقيام بالفعل التالي بسرعة بعد إنهاء فعل، بحذف ます من الفعل. وعند استخدامه مع اسم، يعني الاعتماد على النتيجة.","একটি পরিস্থিতি সত্য ধরে নিয়েও পরের মতামত বা সীমা বলুন। জোড়ায় AにしてもBにしても হলে উভয় ক্ষেত্রেই একই কথা প্রযোজ্য।":"اذكر رأيا أو حدا لاحقا حتى مع افتراض أن موقفا ما صحيح. وعند الاقتران على شكل AにしてもBにしても، ينطبق الشيء نفسه على كلتا الحالتين.","প্রথম বর্ণনাটি পুরো ঠিক নয় মনে করে তার চেয়ে মানানসই দ্বিতীয় বর্ণনা দিন। বিরোধিতা নয়, আরও যথাযথ ভাষায় সংশোধন।":"بظن أن الوصف الأول ليس صحيحا تماما، قدّم وصفا ثانيا أنسب. ليس معارضة، بل تصحيح بلغة أنسب.","একটি কারণকে বিশেষ গুরুত্ব দিয়ে ফলের সঙ্গে জুড়ে দেয়। কারণটি দুর্বল নয়; বক্তা সেটিকেই মূল প্রেরণা হিসেবে সামনে আনছেন।":"يربط تأكيدا خاصا على سبب بالنتيجة. السبب ليس ضعيفا؛ يقدمه المتحدث كالدافع الرئيسي.","একটি কাজ বা অবস্থা ঘটানো ছাড়া পরের কাজ ঘটে। লিখিত বা আনুষ্ঠানিক ভাষায় Vないで-এর কাছাকাছি অর্থ।":"يحدث الفعل التالي دون أن يحدث فعل أو حالة معينة. قريب في المعنى من Vないで في اللغة المكتوبة أو الرسمية.","আগের তথ্য সত্য মেনে নিয়ে পরের অংশে তার প্রত্যাশিত ফল না হওয়ার কথা বলুন। লিখিত বা কিছুটা আনুষ্ঠানিক ব্যাখ্যায় বেশি মানায়।":"بقبول المعلومات السابقة على أنها صحيحة، اذكر أن النتيجة المتوقعة لا تتبع في الجزء اللاحق. يناسب الشروح المكتوبة أو الرسمية نوعا ما بشكل أفضل.","নেতিবাচক কথাটিকে পুরোপুরি মানতে চান না। সীমিত সক্ষমতা, আংশিক সত্য বা শর্তসাপেক্ষ সম্মতি প্রকাশ করেন।":"لا تريد قبول العبارة المنفية تماما. يعبر عن قدرة محدودة أو حقيقة جزئية أو موافقة مشروطة.","একটি তুলনার মানদণ্ড নির্দিষ্ট করে পরের তথ্যের পার্থক্য দেখায়। হার, দাম, অতীত ও বর্তমান তুলনায় কাজে আসে।":"يحدد معيارا للمقارنة ويظهر الفرق في المعلومات اللاحقة. مفيد لمقارنة المعدلات والأسعار والماضي والحاضر.","একটি পরিবর্তন অগ্রসর হওয়ার সঙ্গে অন্য একটি অবস্থাও ধীরে বদলায়। বয়স, সময় বা অভিজ্ঞতার বৃদ্ধি বোঝাতে সুবিধাজনক।":"مع تقدم تغير واحد، تتغير حالة أخرى تدريجيا أيضا. مفيد للتعبير عن ازدياد العمر أو الوقت أو التجربة.","কাজ বা অনুভূতির লক্ষ্য বোঝায়। দুটি পক্ষের বিপরীত বৈশিষ্ট্য তুলনা করতেও ব্যবহার হয়; কোন ব্যবহার তা প্রসঙ্গ দেখে ধরুন।":"يشير إلى هدف فعل أو شعور. ويُستخدم أيضا لمقارنة الخصائص المتقابلة لطرفين؛ حدد الاستخدام المنطبق بناء على السياق.","কোনো অভিজ্ঞতা, মাধ্যম বা ব্যক্তির সাহায্যে ফল পাওয়া বোঝায়। সময়ের বিশেষ্যের সঙ্গে পুরো সময়জুড়েও বোঝাতে পারে।":"يشير إلى أن نتيجة تُحصل بمساعدة تجربة أو وسيلة أو شخص. ومع أسماء الوقت، يمكن أن يشير أيضا إلى المدة بأكملها.","আগের বিষয়টি যাই হোক, পরের ফল বা নিয়ম বদলায় না। বয়স, অভিজ্ঞতা, আবহাওয়া বা অংশগ্রহণের সিদ্ধান্তে ব্যবহার করা যায়।":"بغض النظر عن الأمر السابق، لا تتغير النتيجة أو القاعدة اللاحقة. يمكن استخدامه للعمر أو التجربة أو الطقس أو قرار المشاركة.","ভবিষ্যতে অনাকাঙ্ক্ষিত ফলের সম্ভাবনা বোঝায়। সংবাদ, সতর্কতা ও আনুষ্ঠানিক ব্যাখ্যায় ব্যবহার হয়।":"يشير إلى إمكانية نتيجة غير مرغوبة في المستقبل. يُستخدم في الأخبار والتحذيرات والشروح الرسمية.","একটি সাধারণ অনুমান সবার ক্ষেত্রে ঠিক নয়—এই আংশিক নাকচ প্রকাশ করে। কিছু ক্ষেত্রে সত্য হতে পারে, কিন্তু নিশ্চিত নয়।":"يعبر هذا عن رفض جزئي بأن افتراضا عاما ليس صحيحا للجميع. قد يكون صحيحا في بعض الحالات، لكنه غير مؤكد.","আগেকার অভ্যাস বা বারবার ঘটত এমন অভিজ্ঞতা স্মরণ করে বলুন। এতে স্মৃতিকাতর ভাব থাকতে পারে।":"استخدم هذا لتذكر عادات أو تجارب ماضية كانت تحدث مرارا. قد يحمل هذا شعورا بالحنين."},"lessons.forms":{"必[かなら]ずしも + ইতিবাচক ধারণা + নেতিবাচক predicate":"必[かなら]ずしも + فكرة إيجابية + مسند منفي","Vない・い-বিশেষণくない + ことはない / N・な-বিশেষণでない + ことはない":"Vない・صفة い くない + ことはない / N・صفة な でない + ことはない","Vない-এর ない বাদ + ずにはいられない（する → せずにはいられない）":"احذف ない من Vない + ずにはいられない (する → せずにはいられない)","Plain form + からこそ（N・な-বিশেষণ: だ + からこそ）":"الصيغة العادية + からこそ（N・صفة な: だ + からこそ）","V・い-বিশেষণ plain + 一方[いっぽう]で / な-বিশেষণ + な一方[いっぽう]で / N + である一方[いっぽう]で":"V・صفة い بالصيغة العادية + 一方[いっぽう]で / صفة な + な一方[いっぽう]で / N + である一方[いっぽう]で","সময়・এলাকা・পরিসর N + にわたって / N + にわたる + N":"N للوقت・المنطقة・النطاق + にわたって / N + にわたる + N","Vる・Vている・Vない + 限[かぎ]り / N・な-বিশেষণである + 限[かぎ]り":"Vる・Vている・Vない + 限[かぎ]り / N・صفة な である + 限[かぎ]り","N + とは + সংজ্ঞা・ব্যাখ্যা":"N + ととは + تعريف/شرح","Plain form + とはいえ（N・な-বিশেষণে だ-ও বাদ যায়）":"الصيغة العادية + とはいえ (يُحذف だ أيضا مع N/صفات な)","Vます-stem + 次第[しだい]（সঙ্গে সঙ্গে） / N + 次第[しだい]だ（নির্ভর）":"جذع Vます + 次第[しだい]（بمجرد أن） / N + 次第[しだい]だ（يعتمد على）","Vない-এর ない বাদ + ざるを得[え]ない（する → せざるを得[え]ない）":"Vない دون ない + ざるを得[え]ない (する → せざるを得[え]ない)","V・い-বিশেষণ plain + かのようだ / N・な-বিশেষণ + であるかのようだ":"V / صفة い بالصيغة العادية + かのようだ / N / صفة な + であるかのようだ","V・い-বিশেষণ plain + に違[ちが]いない / N・な-বিশেষণ + に違[ちが]いない":"V・صفة い بالصيغة العادية + に違[ちが]いない / N・صفة な + に違[ちが]いない","V・い-বিশেষণ plain + ものの / な-বিশেষণ + なものの / N + であるものの":"V・صفة い بالصيغة العادية + ものの / صفة な + なものの / N + であるものの","Vた + ものだ（অতীতের স্মৃতি）":"Vた + ものだ (ذكريات الماضي)","V・い-বিশেষণ plain + わけがない / な-বিশেষণ + なわけがない / N + のわけがない":"V・صفة い بالصيغة العادية + わけがない / صفة な + なわけがない / N + のわけがない","Vた + 上[うえ]で（ক্রম） / Vる・Nの + 上[うえ]で（ক্ষেত্র）":"Vた + 上[うえ]で (تسلسل) / Vる・Nの + 上[うえ]で (جانب)","N + に対[たい]して / N + に対[たい]する + N（লক্ষ্য）":"N + に対[たい]して / N + に対[たい]する + N (هدف)"},"lessons.meaning_bn":{"… করা মাত্রই হঠাৎ":"بمجرد أن... فجأة","একদিকে …, অন্যদিকে …":"من جهة ...، ومن جهة أخرى ...","…এর তুলনায়":"...مقارنة بـ","যদিও …, তবু …":"رغم ...، ما زال ...","…কে সূচনা বা উপলক্ষ করে":"... باتخاذه حافزا أو مناسبة","…অনুযায়ী মানিয়ে":"...وفقا لـ","…জুড়ে বিস্তৃতভাবে":"...يمتد عبر / على ...","… বলতে কী বোঝায়":"ما المقصود بـ ...","… না করেই":"...دون أن يفعل ...","… বলার চেয়ে বরং …":"بدلا من القول ...","একেবারে … নয়, তা নয় / কিছুটা সম্ভব":"ليس الأمر أنه ... على الإطلاق / ممكن إلى حد ما","… নির্বিশেষে":"... بغض النظر عن","…কে ভিত্তি করে":"...بناء على / وفقا لـ ...","… হলেই সঙ্গে সঙ্গে / …এর ওপর নির্ভর":"... بمجرد أن / اعتمادا على ...","… না করে উপায় নেই":"لا خيار سوى أن ...","…এর প্রতি / এর বিপরীতে":"...نحو / في مقابل","নিশ্চয়ই … হবে, আমার দৃঢ় ধারণা":"بالتأكيد سيحدث ...، أنا مقتنع تماما","… হওয়ার কোনো কথাই নয়":"لا يمكن أن ... / من المستحيل أن ...","ঠিক … বলেই":"تحديدا لأن ...","… হলো মনে হতেই আবার …":"...بمجرد أن ظن أنه كذلك، على الفور...","…এর সঙ্গে সংশ্লিষ্ট পরিবর্তনে":"...فيما يتعلق بالتغيرات المرتبطة بـ","এমন বলা গেলেও":"حتى لو أمكن القول إن...","… করার পরে / … করার ক্ষেত্রে":"بعد فعل ... / في حالة فعل ...","যতক্ষণ … শর্ত বজায় থাকে":"ما دام شرط ... قائما","একসময় প্রায়ই … করতাম":"كان يفعل... كثيرا في الماضي","…এর মাধ্যমে / …জুড়ে":"من خلال ... / طوال ...","… হলেও / এমনকি … ক্ষেত্রেও":"... حتى لو / حتى في حالة ...","যত …, তত পরিবর্তন":"كلما ...، تغير أكثر","… না করে থাকতে পারি না":"لا يستطيع إلا أن يفعل...","পরিস্থিতিগত কারণে … করা চলে না":"لا يمكن ... بسبب الظروف","অন্য কিছু নয়, ঠিক …ই":"لا شيء سوى ... / ليس سوى ...","মাত্র …, এর বেশি নয়":"مجرد ...، لا أكثر من","শুধু … নয়, অন্যদের ক্ষেত্রেও":"ليس فقط ...، بل للآخرين أيضا","খারাপ কিছু ঘটার আশঙ্কা আছে":"هناك خشية أن يحدث شيء سيئ","সবসময় বা সবার ক্ষেত্রে … নয়":"ليس دائما أو ليس في كل الحالات ...","মনে হয় যেন …":"يبدو وكأن..."},"lessons.quiz.explanation_bn":{"必[かなら]ずしも + とは限[かぎ]らない সাধারণ অনুমানকে আংশিক নাকচ করে।":"必[かなら]ずしも + とは限[かぎ]らない ينفي جزئيا افتراضا عاما.","দুটি নেতিবাচক অংশ সীমিত বা শর্তসাপেক্ষ সক্ষমতা প্রকাশ করে।":"الجزآن المنفيان يعبران عن قدرة محدودة أو مشروطة.","সংখ্যা কম বা সীমিত হিসেবে দেখাতে にすぎない।":"استخدم にすぎない لإظهار رقم على أنه صغير أو محدود.","する-এর ব্যতিক্রমী ず-রূপ せず।":"せず هي صيغة ず غير المنتظمة لـ する.","বিশ্রাম না নিয়ে কাজ চালানোর অর্থে dictionary form + ことなく।":"بمعنى مواصلة العمل دون أخذ راحة، الصيغة المعجمية + ことなく.","ব্যবহারকারী বাড়ার সঙ্গে সম্পর্ক রেখে সেবা বেড়েছে।":"مع ازدياد عدد المستخدمين، توسعت الخدمة وفقا لذلك.","ব্যর্থতা থেকে নতুন পড়ার পদ্ধতির শুরু হয়েছে।":"أدى فشل إلى بداية طريقة جديدة للدراسة.","অভিজ্ঞতা থাকুক বা না থাকুক আবেদন করা যাবে, তাই にかかわらず।":"يمكنك التقديم سواء كانت لديك خبرة أم لا، لذا にかかわらず.","প্রথমে আলোচনা শেষ করে পরে সিদ্ধান্ত, তাই Vた + 上[うえ]で।":"أنهِ النقاش أولا ثم قرر، لذا Vた + 上[うえ]で.","নদীর পানি উপচে পড়া অনাকাঙ্ক্ষিত সম্ভাবনা, তাই おそれがある।":"فيضان النهر احتمال غير مرغوب، لذا おそれがある.","স্তরের সঙ্গে মিলিয়ে বই বদলায়, তাই に応[おう]じて।":"يتغير الكتاب ليتناسب مع المستوى، لذا に応[おう]じて.","উপভাষা কী, তার সংজ্ঞা দেওয়া হচ্ছে।":"يُقدَّم تعريف لما هي اللهجة.","বুকিং করার পরও প্রত্যাশিতভাবে যাওয়া হয়নি; ものの এই অমিল দেখায়।":"حتى بعد إجراء حجز، لم يذهبوا كما هو متوقع؛ ものの يظهر هذا التباين.","ব্যর্থ হওয়াটিকেই প্রস্তুতির গুরুত্ব বোঝার বিশেষ কারণ করা হয়েছে।":"الفشل نفسه جُعل السبب الخاص لفهم أهمية الاستعداد.","জানালা খোলার সঙ্গে সঙ্গে অপ্রত্যাশিত বাতাস—Vた + とたん।":"هبة ريح غير متوقعة في اللحظة التي فُتحت فيها النافذة — Vた + とたん.","পরিশ্রমের ফলই আসল পরিচয়—এই জোরালো মূল্যায়নে にほかならない।":"نتيجة العمل الجاد هي هوية المرء الحقيقية — لهذا التقييم المؤكد، にほかならない.","する ব্যতিক্রমীভাবে せざるを得[え]ない হয়।":"する تصبح بشكل غير منتظم せざるを得[え]ない.","কাজ ছিল সংস্কৃতি শেখার মাধ্যম, তাই を通[とお]して।":"كان العمل وسيلة لتعلم الثقافة، لذا を通[とお]して.","শিক্ষার্থী ছাড়াও শিক্ষক অংশ নেন; সীমা বিস্তৃত হচ্ছে, তাই に限[かぎ]らず।":"يشارك المعلمون أيضا، لا الطلاب فقط؛ النطاق يتسع، لذا に限[かぎ]らず.","終[お]わります থেকে ます বাদ দিয়ে 次第[しだい]; কাজ শেষ হলেই পরিকল্পিত যোগাযোগ।":"احذف ます من 終[お]わります لتحصل على 次第[しだい]؛ يحدث التواصل المخطط بمجرد انتهاء العمل.","সস্তা হওয়া মেনেও কেনার সীমা দেখাচ্ছে।":"حتى مع الإقرار بأنه رخيص، يظهر حدا للشراء.","ব্যাখ্যার ভিত্তি হবে ঘটনা বা তথ্য, তাই に基[もと]づいて।":"سيستند الشرح إلى أحداث أو حقائق، لذا に基[もと]づいて.","ফিরে আসার পরপরই আবার বের হওয়া—দ্রুত অবস্থা বদলাচ্ছে।":"الخروج مرة أخرى مباشرة بعد العودة — الموقف يتغير بسرعة.","কথা বলার ধরনকে উপমা দিয়ে বর্ণনা করায় かのように।":"طريقة الكلام موصوفة بتشبيه، لذا かのように.","関心[かんしん] বিশেষ্যকে বর্ণনা করছে, তাই に対[たい]する।":"إنه يعدّل الاسم 関心[かんしん]، لذا に対[たい]する.","শান্ত হওয়া ও যাতায়াত অসুবিধা—দুটি ভিন্ন দিক, তাই 一方[いっぽう]で।":"كون المكان هادئا وكون المواصلات غير مريحة — جانبان مختلفان، لذا 一方[いっぽう]で.","অভিজ্ঞতা বাড়ার সঙ্গে আত্মবিশ্বাস বাড়ছে—পরিবর্তনের সহগতি।":"مع ازدياد الخبرة، تنمو الثقة أيضا — تغيرات تتحرك معا.","রাগের বর্ণনা বদলে বিপাকে পড়াকে বেশি যথাযথ বলা হচ্ছে।":"بدلا من وصفها بالغضب، يقال إن وصفها بأنها في ورطة أدق.","এখানে বসবাসের শর্ত বজায় থাকাকালীন নিয়ম মানতে হবে।":"هنا، يجب اتباع القواعد ما دامت حالة العيش هنا مستمرة.","ব্যস্ততা মেনেও যোগাযোগের প্রয়োজন বোঝানো হয়েছে।":"حتى مع الإقرار بالانشغال، ينقل أن التواصل ضروري.","দুই সপ্তাহজুড়ে সাক্ষাৎকার নেওয়ার বিস্তার বোঝাচ্ছে।":"يشير إلى إجراء مقابلات على مدى أسبوعين.","আলো জ্বলছে দেখে কেউ আছেন বলে দৃঢ় অনুমান করা হয়েছে।":"برؤية الضوء مضاء، يُفترض بحزم أن شخصا ما موجود.","এটি দেরি করার সামর্থ্যের প্রশ্ন নয়; গুরুত্বপূর্ণ সভায় দেরি করা চলে না।":"هذه ليست مسألة قدرة على التأخر؛ لا يجب التأخر عن اجتماع مهم.","গত মাস হচ্ছে তুলনার ভিত্তিকাল, তাই に比[くら]べて।":"الشهر الماضي هو فترة الأساس للمقارنة، لذا に比[くら]べて.","অতীতের পুনরাবৃত্ত অভ্যাস স্মরণ করতে Vた + ものだ।":"لتذكر عادة متكررة من الماضي، Vた + ものだ.","কোনোভাবেই বলার কথা নয়—দৃঢ় অস্বীকারে わけがない।":"لا يمكن أن يقول ذلك — للإنكار الحازم، わけがない."},"lessons.quiz.options":{"পড়তে একেবারে পারি না, তা নয়":"ليس الأمر أنني لا أستطيع القراءة على الإطلاق","একেবারেই পড়তে পারি না":"لا أستطيع القراءة على الإطلاق","অবশ্যই নিখুঁতভাবে পড়ি":"أقرأ بالتأكيد بشكل مثالي"},"lessons.quiz.prompt":{"দৃঢ় অস্বীকার:「彼[かれ]がそんなことを言[い]う（　）。」":"إنكار حازم: 「彼[かれ]がそんなことを言[い]う（　）。」","「読[よ]めないことはない。」—কোন অর্থ?":"「読[よ]めないことはない。」 — ماذا يعني؟","「二週間[にしゅうかん]（　）、社員[しゃいん]に話[はなし]を聞[き]いた。」—সময়ের বিস্তার।":"「二週間[にしゅうかん]（　）、社員[しゃいん]に話[はなし]を聞[き]いた。」 — مدى زمني.","する-এর সঠিক রূপ:「心配[しんぱい]（　）にはいられない。」":"الصيغة الصحيحة لـ する: 「心配[しんぱい]（　）にはいられない。」","「失敗[しっぱい]（　）、勉強[べんきょう]の方法[ほうほう]を変[か]えた。」—পরিবর্তনের সূচনা।":"「失敗[しっぱい]（　）、勉強[べんきょう]の方法[ほうほう]を変[か]えた。」 — حافز التغير.","「仕事[しごと]（　）、地域[ちいき]の文化[ぶんか]を学[まな]んだ。」—মাধ্যম।":"「仕事[しごと]（　）、地域[ちいき]の文化[ぶんか]を学[まな]んだ。」 — وسيلة / وسيط.","「成功[せいこう]は努力[どりょく]の結果[けっか]（　）。」—দৃঢ় মূল্যায়ন।":"「成功[せいこう]は努力[どりょく]の結果[けっか]（　）。」 — تقييم مؤكد.","「先月[せんげつ]（　）、売上[うりあげ]が下[さ]がった。」—তুলনা।":"「先月[せんげつ]（　）、売上[うりあげ]が下[さ]がった。」 — مقارنة.","দৃঢ় অনুমান:「電気[でんき]がついている。誰[だれ]かいる（　）。」":"افتراض حازم: 「電気[でんき]がついている。誰[だれ]かいる（　）。」","「すべて分[わ]かっている（　）話[はな]す。」—যেন সব জানে।":"「すべて分[わ]かっている（　）話[はな]す。」 — وكأنه يعرف كل شيء.","「大雨[おおあめ]で川[かわ]があふれる（　）。」—অনাকাঙ্ক্ষিত ঝুঁকি।":"「大雨[おおあめ]で川[かわ]があふれる（　）。」 — خطر غير مرغوب.","「忙[いそが]しい（　）、連絡[れんらく]は必要[ひつよう]だ。」—শর্ত মেনে সীমা।":"「忙[いそが]しい（　）、連絡[れんらく]は必要[ひつよう]だ。」 — قبول شرط وإظهار حد.","「環境[かんきょう]問題[もんだい]（　）関心[かんしん]が高[たか]い。」—লক্ষ্যবিষয়।":"「環境[かんきょう]問題[もんだい]（　）関心[かんしん]が高[たか]い。」 — موضوع مستهدف.","শেষ হলেই জানাব:「終[お]わり（　）、連絡[れんらく]します。」":"سأخبرك بمجرد أن ينتهي: 「終[お]わり（　）、連絡[れんらく]します。」","「経験[けいけん]が増[ふ]える（　）、自信[じしん]もつく。」—ক্রমে পরিবর্তন।":"「経験[けいけん]が増[ふ]える（　）、自信[じしん]もつく。」 — تغير تدريجي.","「失敗[しっぱい]した（　）、次[つぎ]は準備[じゅんび]を大切[たいせつ]にする。」—কারণে জোর।":"「失敗[しっぱい]した（　）、次[つぎ]は準備[じゅんび]を大切[たいせつ]にする。」 — تأكيد على السبب.","「この町[まち]は静[しず]かな（　）、交通[こうつう]が不便[ふべん]です。」—দুটি দিক।":"「この町[まち]は静[しず]かな（　）、交通[こうつう]が不便[ふべん]です。」 — جانبان.","「休[やす]む（　）、作業[さぎょう]を続[つづ]けた。」—না করে।":"「休[やす]む（　）、作業[さぎょう]を続[つづ]けた。」 — دون أن يفعل.","আগে আলোচনা, তারপর সিদ্ধান্ত:「相談[そうだん]（　）上[うえ]で、決[き]めます。」":"ناقش أولا، ثم قرر: 「相談[そうだん]（　）上[うえ]で、決[き]めます。」","「学生[がくせい]（　）、先生[せんせい]も参加[さんか]します。」—শিক্ষার্থীর বাইরেও প্রযোজ্য।":"「学生[がくせい]（　）、先生[せんせい]も参加[さんか]します。」 — ينطبق على غير الطلاب أيضا.","「帰[かえ]ってきた（　）、また出[で]かけた。」—দ্রুত পালাবদল।":"「帰[かえ]ってきた（　）、また出[で]かけた。」 — تحول سريع.","する-এর সঠিক রূপ:「中止[ちゅうし]（　）を得[え]ない。」":"الصيغة الصحيحة لـ する: 「中止[ちゅうし]（　）を得[え]ない。」","「レベル（　）、教材[きょうざい]を変[か]えます。」—মানিয়ে নেওয়া।":"「レベル（　）、教材[きょうざい]を変[か]えます。」 — التكيف / التعديل.","সংজ্ঞা:「方言[ほうげん]（　）、ある地域[ちいき]で使[つか]われる言葉[ことば]だ。」":"تعريف: 「方言[ほうげん]（　）、ある地域[ちいき]で使[つか]われる言葉[ことば]だ。」","「事実[じじつ]（　）、説明[せつめい]してください。」—ভিত্তি।":"「事実[じじつ]（　）、説明[せつめい]してください。」 — أساس.","「怒[おこ]っている（　）、困[こま]っているようだ。」—আরও যথাযথ বর্ণনা।":"「怒[おこ]っている（　）、困[こま]っているようだ。」 — وصف أدق.","পুরোনো অভ্যাস:「学生時代[がくせいじだい]は、よく図書館[としょかん]へ（　）ものだ。」":"عادة قديمة: 「学生時代[がくせいじだい]は、よく図書館[としょかん]へ（　）ものだ。」","「大切[たいせつ]な会議[かいぎ]なので、遅[おく]れる（　）。」—দায়িত্ববোধ।":"「大切[たいせつ]な会議[かいぎ]なので、遅[おく]れる（　）。」 — شعور بالمسؤولية.","「参加者[さんかしゃ]は十人[じゅうにん]（　）。」—মাত্র দশজন।":"「参加者[さんかしゃ]は十人[じゅうにん]（　）。」 — عشرة أشخاص فقط."},"lessons.tip_bn":{"する-এর রূপ せざる; しざる নয়। নিজের আগ্রহে পছন্দ করা কাজের জন্য নয়।":"صيغة する هي せざる؛ وليست しざる. وهذا ليس للمهام التي يختارها المرء باهتمامه الخاص.","わけではない = পুরোপুরি এমন নয়; わけがない = কোনোভাবেই এমন হওয়ার কথা নয়।":"わけではない = ليس بالضرورة كذلك؛ わけがない = لا يمكن أن يكون كذلك بأي حال.","এই পাঠে সংজ্ঞার ব্যবহার; とは思[おも]わなかった-তে বিস্ময়ের ব্যবহার আলাদা।":"في هذا الدرس، الاستخدام للتعريفات؛ والاستخدام المعبر عن الدهشة في とは思[おも]わなかった مختلف.","কারণ জানাতে からにほかならない; শুধু বিশেষ্যের পরিচয় জোর দিতে にほかならない।":"لذكر سبب استخدم からにほかならない؛ وللتأكيد ببساطة على هوية اسم، استخدم にほかならない.","অভিজ্ঞতার মাধ্যমে শেখা এবং সারা বছরজুড়ে—এই দুই ব্যবহার প্রসঙ্গ দেখে আলাদা করুন।":"ميّز بين هذين الاستخدامين — التعلم من خلال التجربة وطوال العام بأكمله — بناء على السياق.","যদিও গ্রীষ্ম, তবু পাহাড়ে ঠান্ডা—এই ধরনের স্বীকারের পর সীমা দেখায়।":"رغم أنه الصيف، الجو بارد في الجبال — يظهر حدودا بعد مثل هذا الإقرار.","だけでなく-এর মতো বিস্তার বোঝায়; “এই সময়ের মধ্যে সীমাবদ্ধ” অর্থের に限[かぎ]り আলাদা।":"مثل だけでなく، يشير إلى التوسع؛ وに限[かぎ]り بمعنى «محدود ضمن هذا الوقت» مختلف.","জোরপূর্বক বাইরের বাধ্যবাধকতা নয়; হাসি, চিন্তা, কান্নার মতো ভেতরের তাড়না প্রধান।":"ليس التزاما خارجيا مفروضا؛ الدوافع الداخلية مثل الضحك والأفكار والبكاء هي الأساسية.","に応[おう]じて শর্ত অনুযায়ী বদলায়; にかかわらず শর্তে বদলায় না।":"に応[おう]じて يتغير وفقا للشروط؛ にかかわらず لا يتغير تبعا للشروط.","遅[おく]れるにしても মানে দেরি হলেও; দেরি করার অনুমতি দেওয়া নয়।":"遅[おく]れるにしても يعني حتى لو تأخر المرء؛ ولا يعني منح إذن بالتأخر.","দুটি ঘটনা শুধু পাশাপাশি নয়; সম্পর্কিত পরিবর্তন দেখাতে হবে।":"يجب أن يظهر أن الحدثين ليسا مجرد متجاورين؛ بل تغيرات مرتبطة.","食[た]べられないことはない = খাওয়া একেবারে অসম্ভব নয়; স্বচ্ছন্দে খেতে পারি এমন জোর নেই।":"食[た]べられないことはない = الأكل ليس مستحيلا تماما؛ ليس هناك شعور قوي بأن المرء يستطيع أكله براحة.","নিয়মিত “এর পরে” বলার জন্য てから যথেষ্ট; とたん হঠাৎ ঘটার অনুভূতি দেয়।":"لـ«بعد ذلك» العادي، てから كاف؛ とたん يعطي شعورا بشيء يحدث فجأة.","কিসের সঙ্গে তুলনা করছেন তা পরিষ্কার রাখুন; শুধু সংখ্যা বললেই তুলনা সম্পূর্ণ হয় না।":"حافظ على وضوح ما تقارن به؛ مجرد ذكر الأرقام لا يكمل مقارنة.","পরের বিশেষ্যকে বর্ণনা করলে かのようなN; ক্রিয়াকে বর্ণনা করলে かのようにV।":"عند تعديل اسم لاحق، استخدم かのようなN؛ وعند تعديل فعل، استخدم かのようにV.","রূপ বদলালে অর্থ বদলায়: 確認[かくにん]した上[うえ]で = যাচাইয়ের পরে; 働[はたら]く上[うえ]で = কাজ করার ক্ষেত্রে।":"عندما تتغير الصيغة، يتغير المعنى: 確認[かくにん]した上[うえ]で = بعد التحقق؛ 働[はたら]く上[うえ]で = عند العمل / في سياق العمل.","মাত্র তিনজন = 三人[さんにん]にすぎない; প্রায় তিনজন = 三人[さんにん]ぐらい—অর্থ আলাদা।":"ثلاثة أشخاص فقط = 三人[さんにん]にすぎない؛ حوالي ثلاثة أشخاص = 三人[さんにん]ぐらい — المعاني مختلفة.","আগের ঘটনাটি পরের পরিবর্তনের শুরু; দৈনন্দিন ছোট কারণেও সবসময় ব্যবহার করবেন না।":"الحدث السابق هو بداية التغير اللاحق؛ لا تستخدمه لكل سبب يومي صغير.","Vる + 一方[いっぽう]だ শুধু পরিবর্তন এক দিকেই এগোনো বোঝাতে পারে; এই পাঠে শেষে で আছে।":"Vる + 一方[いっぽう]だ يمكن أن يشير ببساطة إلى تغير يتقدم في اتجاه واحد؛ في هذا الدرس، で يأتي في النهاية.","বাক্যের পরের অংশে আগের শর্ত অনুযায়ী মানিয়ে নেওয়ার সম্পর্ক খুঁজুন।":"ابحث عن العلاقة في الجزء الأخير من الجملة حيث يتكيف وفقا للشرط في الجزء الأول.","から সাধারণ কারণ, からこそ সেই কারণকে জোর দেয়। পরে ইতিবাচক উপদেশ বা মূল্যায়ন প্রায়ই আসে।":"から سبب عام، بينما からこそ يؤكد ذلك السبب. وغالبا ما تتبعه نصيحة أو تقييم إيجابي.","নিশ্চয়তা অনুভব করলেও এটি অনুমান; হুবহু “প্রমাণিত সত্য” নয়।":"حتى لو شعرت بيقين قوي، فهذا تخمين؛ وليس «حقيقة مثبتة» دقيقة.","সাধারণ “ভাবছি” অর্থ নয়। দ্রুত পালাবদল; নিজের ইচ্ছাকৃত ধারাবাহিক কাজ বোঝাতে কম মানায়।":"ليس المعنى العادي لـ«التفكير». تناوب سريع؛ أقل ملاءمة للتعبير عن أفعال المرء المتسلسلة المقصودة.","সরাসরি dictionary form লাগে: 休[やす]むことなく; 休[やす]まないことなく লিখবেন না।":"تُستخدم الصيغة المعجمية مباشرة: 休[やす]むことなく؛ لا تكتب 休[やす]まないことなく.","এই পাঠে শর্তের ব্যবহার। 時間[じかん]の限[かぎ]り মানে সময়ের শেষ সীমা পর্যন্ত—প্রসঙ্গ আলাদা।":"في هذا الدرس، الاستخدام للشروط. 時間[じかん]の限[かぎ]り يعني حتى الحد الأقصى للوقت — السياق مختلف.","পরের অংশে পরিবর্তন দিন; একটি নির্দিষ্ট মুহূর্তের সিদ্ধান্ত বা সরাসরি আদেশ মানায় না।":"في الجزء التالي، قدّم تغيرا؛ لا يناسب قرار لحظة واحدة أو أمرا مباشرا.","終[お]わり次第[しだい] = শেষ হলেই; 天気[てんき]次第[しだい] = আবহাওয়ার ওপর নির্ভর।":"終[お]わり次第[しだい] = بمجرد أن ينتهي؛ 天気[てんき]次第[しだい] = يعتمد على الطقس.","ভালো ফলের সম্ভাবনায় সাধারণত使[つか]わない; 危険[きけん] বা ক্ষতির পূর্বাভাসে মানায়।":"عموما لا يُستخدم 使[つか]わない لاحتمال نتيجة جيدة؛ يناسب توقعات 危険[きけん] أو الضرر.","একবারের সাম্প্রতিক ঘটনা নয়। ものだ-এর সাধারণ সত্য বা উপদেশের ব্যবহার থেকে এটি আলাদা।":"ليس حدثا حديثا لمرة واحدة. وهذا متميز عن الاستخدام العام للحقيقة أو النصيحة لـ ものだ.","সরাসরি অক্ষমতা できない থেকে আলাদা। 休[やす]まないわけにはいかない মানে বিশ্রাম নিতেই হবে।":"مختلف عن العجز المباشر، できない. 休[やす]まないわけにはいかない يعني أن المرء يجب أن يأخذ راحة.","একটি নির্দিষ্ট মুহূর্তের জন্য নয়। 一時間[いちじかん]にわたる説明[せつめい] মানে এক ঘণ্টাজুড়ে ব্যাখ্যা।":"ليس للحظة محددة واحدة. 一時間[いちじかん]にわたる説明[せつめい] يعني شرحا يمتد ساعة واحدة.","দুটি বিকল্পের মধ্যে দ্বিতীয়টি বেশি সঠিক—এই দিকটি খেয়াল রাখুন।":"ضع في اعتبارك أنه بين بديلين، الثاني أدق.","পুরোপুরি অসম্ভব অর্থ নয়। 必[かなら]ずしも-এর সঙ্গে শেষে নেতিবাচক অর্থ রাখুন।":"لا يعني مستحيلا تماما. حافظ على معنى منفي في النهاية مع 必[かなら]ずしも.","বিশেষ্যের আগে に対[たい]する: 先生[せんせい]に対[たい]する質問[しつもん]।":"قبل اسم، に対[たい]する: 先生[せんせい]に対[たい]する質問[しつもん].","単[たん]に “অনুযায়ী” নয়; সিদ্ধান্তের ভিত্তির সঙ্গে দৃঢ় সম্পর্ক আছে।":"ليس ببساطة 単[たん]に «وفقا لـ»؛ له ارتباط قوي بأساس القرار.","ものの-এর পরে বাস্তব ফল বা অবস্থা দিন। শুধু দুটি কাজের ক্রম বোঝাতে ব্যবহার করবেন না।":"قدّم النتيجة أو الموقف الفعلي بعد ものの. لا تستخدمه فقط لإظهار الترتيب الزمني لفعلين."},"scope_bn":{"QUARTET II-এর ৭–১২ অধ্যায়ের থিম অনুসরণে নির্বাচিত ৩৬টি গ্রামারের নিজস্ব সহায়ক অনুশীলন। এটি মূল বইয়ের সম্পূর্ণ গ্রামার সূচি নয়।":"تدريب مساعد أصلي على 36 نقطة قواعد مختارة بناء على موضوعات الفصول 7-12 من QUARTET II. هذا ليس فهرس القواعد الكامل للكتاب الرئيسي."},"study.dialogue":{"ঠিক বলেছেন। এখনই যোগাযোগ করে দেখব।":"أنت محق. سأتواصل معهم على الفور.","হ্যাঁ। যাচাই করার পরে সিদ্ধান্ত নিই।":"نعم. لنتخذ قرارا بعد التحقق.","নির্দেশনার কাগজ বাড়ালে কেমন হয়?":"ما رأيك في زيادة ورقة التعليمات؟","আজ আপনার বাসায় আসতে পারি?":"هل يمكنني المجيء إلى منزلك اليوم؟","কিছু হয়েছে?":"هل حدث شيء ما؟","গ্রাহকসেবার ক্ষেত্রে কোন বিষয়কে গুরুত্ব দেন?":"ما الذي تعتبره مهما في خدمة العملاء؟","আচ্ছা। তাহলে সুবিধামতো একটি দিন জানাবেন?":"فهمت. إذن هل يمكنك إخباري بيوم مناسب؟","আগামীকাল একটু সাহায্য করবেন?":"هل يمكنك مساعدتي قليلا غدا؟","আগে ব্যবহারকারীদের জিজ্ঞেস করে দেখব?":"هل أسأل المستخدمين مسبقا؟","এই গ্রাফ থেকে কী বোঝা যায়?":"ما الذي يمكن فهمه من هذا الرسم البياني؟","রবিবার হলে পারব।":"إذا كان يوم الأحد، أستطيع فعل ذلك.","এটিও একটি উপায়, তবে ভাষা বদলানোর প্রয়োজনও আছে বলে মনে করি।":"هذه أيضا طريقة، لكنني أظن أن هناك حاجة أيضا لتغيير اللغة.","তাহলে রবিবার হলে কেমন হয়?":"إذن ما رأيك في يوم الأحد؟","প্রথমে গ্রাহকের চাহিদা নিশ্চিত করি।":"أولا، أؤكد احتياجات العميل.","স্টেশনে খোঁজ নিয়ে দেখলে কেমন হয়?":"ما رأيك في التحقق في المحطة؟","কিছু কথা জিজ্ঞেস করতে পারি?":"هل يمكنني أن أسألك بعض الأشياء؟","একটি গুরুত্বপূর্ণ খাতা হারিয়ে ফেলেছি।":"لقد فقدت دفترا مهما.","আগামীকাল কাজ আছে বলে পারব না।":"لدي عمل غدا، لذا لن أستطيع.","দুঃখিত, আজ আমার অন্য কাজ আছে।":"آسف، لدي أشياء أخرى لأفعلها اليوم.","অন্য স্কুলেও কি একই রকম হবে?":"هل سيكون الأمر نفسه في مدارس أخرى؟","ট্রেন ব্যবহারকারী সবচেয়ে বেশি।":"مستخدمو القطار هم الأعلى.","জি, বলুন।":"نعم، تفضل من فضلك.","শনিবার বিকেল হলে ঠিক আছে।":"بعد ظهر السبت سيكون مناسبا.","শুধু এই জরিপ থেকে তা বিচার করা যায় না।":"لا يمكن الحكم على ذلك من هذا الاستطلاع وحده."},"study.kanji":{"বোঝা বা সমাধান":"الفهم أو الحل","তুলনা":"المقارنة","দৃশ্য":"المشهد","প্রত্যাশা":"التوقع","বৃদ্ধি":"الزيادة","মিলিত সহযোগিতা":"التعاون المشترك","বাহিরে প্রকাশ":"التعبير الخارجي","অনুভূতি বা অবস্থা":"الشعور أو الحالة","অতিথি বা ক্রেতা":"الضيف أو العميل","অভ্যস্ত":"معتاد","মনের ভাব":"حالة الذهن","ধারণা বা চিন্তা":"المفهوم أو الفكرة","বদলানো":"التغير","বিবেচনা":"الاعتبار","ভিন্ন":"مختلف","ভরসা":"الاعتماد","হ্রাস":"النقصان","রূপ বা ছাপ":"الشكل أو الانطباع"},"study.listening_answer":{"এ সপ্তাহে প্রশ্ন তৈরি হবে; আগামী সপ্তাহে লাইব্রেরির প্রবেশপথে জরিপ হবে।":"ستُنشأ الأسئلة هذا الأسبوع؛ وسيُجرى الاستطلاع عند مدخل المكتبة الأسبوع المقبل.","জীবনবৃত্তান্ত আনতে হবে; আগামী মঙ্গলবার বেলা ৩টার মধ্যে অফিসে আসতে হবে; পরিবর্তন চাইলে আগের দিনের মধ্যে ফোন করতে হবে।":"تحتاج إلى إحضار سيرة ذاتية؛ ويجب أن تصل إلى المكتب بحلول الساعة 3:00 بعد الظهر يوم الثلاثاء المقبل؛ وإذا أردت إجراء تغييرات، يجب أن تتصل بحلول اليوم السابق.","শনিবার বেলা ২টা; স্টেশনের সামনের লাইব্রেরি; শুক্রবারের মধ্যে জানাতে হবে।":"السبت الساعة 2:00 بعد الظهر؛ المكتبة أمام المحطة؛ يجب الرد بحلول يوم الجمعة.","মঙ্গলবার বিকেলে পারবেন; সময়সূচি বদলানো যাবে কি না যাচাই করতে বলছেন।":"يمكنهم فعل ذلك بعد ظهر الثلاثاء؛ ويطلبون التحقق مما إذا كان يمكن تغيير الجدول.","সকালে ৬÷১০ = ৬০ শতাংশ; নির্দিষ্ট সময় নেই একজনের। এগুলো অনুশীলনের সংখ্যা।":"في الصباح 6÷10 = 60 بالمئة؛ شخص واحد ليس لديه وقت محدد. هذه أرقام للتدريب.","গতকাল দোকানে যে আসনে বসেছিলেন সেখানে; আজ সন্ধ্যায় নিতে যাবেন।":"في المقعد الذي جلست فيه في المتجر أمس؛ ستذهب لأخذه هذا المساء."},"study.listening_question":{"ব্যাগ কোথায় পাওয়া গেছে? বক্তা কখন নিতে যাবেন?":"أين وُجدت الحقيبة؟ متى سيذهب المتحدث لأخذها؟","কী আনতে হবে, কখন আসতে হবে, পরিবর্তন চাইলে কী করবেন?":"ما الذي يجب إحضاره، ومتى يجب المجيء، وما الذي يجب فعله إذا أردت إجراء تغييرات؟","সকালে পড়ার অনুপাত কত? নির্দিষ্ট সময় নেই কতজনের?":"ما نسبة الدراسة في الصباح؟ كم شخصا ليس لديه وقت محدد؟","কখন, কোথায় এবং কত দিনের মধ্যে জানাতে হবে?":"متى وأين وبحلول متى ينبغي أن أرد؟","এ সপ্তাহে কী হবে? জরিপ কোথায় এবং কখন হবে?":"ما الذي سيحدث هذا الأسبوع؟ أين ومتى سيُجرى الاستطلاع؟","বক্তা কোন দিন পারবেন? শ্রোতার কাছে কী অনুরোধ করছেন?":"في أي يوم يستطيع المتحدث فعل ذلك؟ وما الذي يطلبه من المستمع؟"},"study.questions":{"সবার কাছে একই ব্যাখ্যা যথেষ্ট নয় কেন?":"لماذا لا يكفي الشرح نفسه للجميع؟","মিনা যাওয়ার আগে কী করেনি?":"ما الذي لم تفعله مينا قبل المغادرة؟","গ্রাহকের প্রয়োজন অনুযায়ী ব্যাখ্যা মানিয়ে নেওয়া।":"تكييف الشروح لتناسب احتياجات العميل.","প্রথমবার আসা ব্যক্তির উদাহরণটি কী বোঝায়?":"ما الذي يوضحه مثال الزائر لأول مرة؟","দৃষ্টিকোণ বদলানোর কারণ কী ছিল?":"ما سبب تغيير وجهة النظر؟","লেখাটির মূল শিক্ষা কী?":"ما الدرس الرئيسي من النص؟","পরের বাক্যে কাজ থাকার কারণ ও রবিবারের বিকল্প দেওয়ার তথ্য থেকে।":"من المعلومات حول وجود عمل في الجملة التالية وتقديم بديل يوم الأحد.","ট্রেন ব্যবহারকারীর অনুপাত কত এবং কীভাবে পেলেন?":"ما نسبة مستخدمي القطار وكيف حصلت عليها؟","প্রথমে কাগজ বাড়াতে চেয়েছিল; পরে ব্যবহারকারীর প্রয়োজন বুঝে ভাষা সহজ করেছে।":"أولا، أرادوا زيادة الورقة؛ لاحقا، بعد فهم احتياجات المستخدم، بسّطوا اللغة.","খাতা পাওয়া গেছে বলে স্টেশনের খবর আসার পর।":"بعد أن جاءت الأخبار من المحطة بأن الدفتر وُجد.","না; আগামীকাল পারবে না, রবিবার পারবে বলে বিকল্প দিয়েছে।":"لا؛ لا يستطيعون فعل ذلك غدا، لكنهم قدموا بديلا بقولهم إنهم يستطيعون يوم الأحد.","ব্যবহারকারীদের সঙ্গে কথা বলে সমস্যাটি শ্রেণিবিভাগের নাম বুঝতে অসুবিধা বলে জানা যায়।":"بالتحدث مع المستخدمين، عُلم أن المشكلة هي صعوبة فهم أسماء الفئات.","আমন্ত্রণের ভাষা শুনে সময় ধরে না নিয়ে পরিস্থিতি যাচাই ও আলোচনা করা দরকার।":"بدلا من الافتراض بناء على لغة الدعوة، من الضروري التحقق من الموقف والمناقشة.","১২÷২০×১০০ = ৬০ শতাংশ।":"12÷20×100 = 60 بالمئة.","কোন ঘটনায় ইউয়ের অনুভূতি বদলাল?":"أي حدث غيّر مشاعر يو؟","প্রথম প্রস্তাব ও শেষ পদক্ষেপ কীভাবে আলাদা?":"كيف يختلف الاقتراح الأول عن الخطوة الأخيرة؟","গ্রাহকের অভিজ্ঞতা ও চাহিদা আলাদা; সে অনুযায়ী ক্রম ও ভাষা বদলাতে হয়।":"تجارب العملاء واحتياجاتهم تختلف؛ ويجب تعديل الترتيب واللغة وفقا لذلك.","না; খাতা হারিয়ে ইউয়ের অনুভূতির উপমা। かのように সূত্রটি দেখুন।":"لا؛ إنه تشبيه لمشاعر يو عند فقدان الدفتر. انظر قاعدة かのように.","কথাগুলো মুছে যাওয়ার বর্ণনাটি কি বাস্তব ঘটনা?":"هل وصف الكلمات وهي تُمحى حدث حقيقي؟","বন্ধুর সময় আছে কি না যোগাযোগ করে নিশ্চিত করেনি। দ্বিতীয় ও তৃতীয় বাক্য মিলিয়ে বুঝবেন।":"لم تتواصل مع صديقتها للتأكد مما إذا كان لديها وقت. يمكنك فهم هذا بدمج الجملتين الثانية والثالثة.","難[むずか]しい-এর উদ্দেশ্য কোন তথ্য থেকে নিশ্চিত হলেন?":"من أي معلومات أكدت ما كان المقصود بـ 難[むずか]しい؟","এই কথোপকথনে বন্ধু কি সাহায্য একেবারে অস্বীকার করেছে?":"هل رفض الصديق المساعدة تماما في هذه المحادثة؟","উত্তরদাতা কেবল একটি ক্লাসের ২০ জন; নমুনা জাতীয় প্রতিনিধিত্ব নিশ্চিত করে না।":"المستجيبون هم 20 شخصا فقط في فصل واحد؛ العينة لا تضمن تمثيلا وطنيا.","কেন সারা জাপানের বিষয়ে সিদ্ধান্ত নেওয়া যায় না?":"لماذا لا يمكن اتخاذ قرارات بشأن اليابان بأكملها؟"},"study.reading":{"たとえば-এর উদাহরণ আগের মানিয়ে নেওয়ার বক্তব্যকে স্পষ্ট করে।":"مثال たとえば يوضح العبارة السابقة حول التكيف.","পরের কারণ ও বিকল্প দিন থেকে আগের কথার উদ্দেশ্য পরিষ্কার হয়।":"غرض الملاحظة السابقة يتضح من السبب اللاحق واليوم البديل.","অন্য দৃষ্টিকোণ থেকে ভাবাই উন্নতির সূচনা হলো।":"التفكير من وجهة نظر أخرى هو بداية التحسين.","একটি ছোট দোকানের ম্যানেজারকে জিজ্ঞেস করলাম, কাজের কোন বিষয়টিকে গুরুত্ব দেন।":"سألت مدير متجر صغير عما يعتبره مهما في عمله.","কাগজ কম থাকা নয়, নামের অর্থ না বোঝা—সমস্যার ব্যাখ্যা বদলাল।":"ليس الأمر وجود أوراق أقل، بل عدم فهم معنى الأسماء — تغير شرح المشكلة.","এই বাক্য গল্পের মোড় বদলায়; আগের উদ্বেগের বিপরীতে ভালো খবর।":"هذه الجملة تقلب حبكة القصة؛ أخبار جيدة على خلفية قلق سابق.","সমাধান হিসেবে আলোচনা এসেছে; কোনো দেশের সব মানুষকে নিয়ে নিয়ম বলা হয়নি।":"ظهر النقاش كحل؛ لم تُذكر قاعدة عن جميع أهل بلد معين.","শেষ বাক্য ঘটনাটির সাধারণ শিক্ষা; উদাহরণের বাইরে অতিরিক্ত ফল দাবি করা হয়নি।":"الجملة الأخيرة هي الدرس العام من الحدث؛ لا تُدعى نتائج إضافية تتجاوز المثال.","ক্লাসের অনুশীলনের জন্য ধরে নিই, ২০ শিক্ষার্থীকে যাতায়াতের উপায় জিজ্ঞেস করা হলো।":"للتدريب في الفصل، لنفترض أن 20 طالبا سُئلوا عن وسيلة نقلهم.","ম্যানেজার বললেন, “একই ব্যাখ্যা বারবার বলাই যথেষ্ট নয়।”":"قال المدير: «تكرار الشرح نفسه مرارا ليس كافيا.»","তার মনে হলো, যেন গুরুত্বপূর্ণ কথাগুলোও হারিয়ে গেছে।":"شعر وكأن حتى الكلمات المهمة قد فُقدت.","しかし আগের প্রত্যাশার সঙ্গে বাস্তব অবস্থার অমিল আনে।":"しかし يقدم تباينا بين التوقع السابق والموقف الفعلي.","এই দৃশ্যে কী বোঝায় বলা হয়েছে; সব ক্ষেত্রে একই অর্থ দাবি করা হয়নি।":"يُشرح ما يعنيه هذا المشهد؛ لا يُدعى المعنى نفسه لكل الحالات.","খাতাটি হাতে পেয়ে ইউ না হেসে থাকতে পারল না।":"عند استلام الدفتر بيده، لم يستطع يو إلا أن يبتسم.","পরদিন স্টেশন থেকে জানানো হলো খাতাটি পাওয়া গেছে।":"في اليوم التالي، أبلغت المحطة أن الدفتر وُجد.","দুজন সময়সূচি নিশ্চিত করার গুরুত্ব নিয়ে আলোচনা করল।":"ناقش الاثنان أهمية تأكيد الجداول.","কিন্তু বন্ধু তখন কাজে বের হওয়ার ঠিক আগের অবস্থায় ছিল।":"لكن الصديق كان على وشك المغادرة للعمل في ذلك الوقت.","তারপর বলল, “কাজ আছে, তবে রবিবার হলে সাহায্য করতে পারব।”":"ثم قال: «لدي عمل، لكن إذا كان يوم الأحد، أستطيع المساعدة.»","এটি অনুশীলনের কাল্পনিক জরিপ; বাস্তব গবেষণা নয়।":"هذا استطلاع افتراضي للتدريب؛ ليس بحثا فعليا.","বন্ধু বলল, “আগামীকাল একটু কঠিন হবে।”":"قال الصديق: «غدا سيكون صعبا قليلا.»","প্রথম বাক্যে সমস্যাটি এসেছে; খাতাটির দৈনন্দিন গুরুত্বও জানা গেল।":"ظهرت المشكلة في الجملة الأولى؛ وكُشفت أيضا الأهمية اليومية للدفتر.","বাসায় পৌঁছানো মাত্র সে বিষয়টি টের পেল।":"بمجرد أن وصل إلى المنزل، أدرك الأمر.","অনুরোধের বিষয় ও সময় আগে দেওয়া হয়েছে।":"أُعطي موضوع الطلب وتوقيته مسبقا.","পরদিন সে কোনো যোগাযোগ না করেই বন্ধুর বাসায় গেল।":"في اليوم التالي، ذهبت إلى منزل صديقتها دون أي تواصل.","しかし উপসংহারের সীমা নির্দেশ করে।":"しかし يشير إلى حد الاستنتاج.","মোট ১২+৫+৩=২০; গণনার ভিত্তি একই আছে।":"المجموع 12+5+3=20؛ أساس الحساب يبقى كما هو.","শেষ বাক্য লেখার মূল শিক্ষা।":"الدرس الأساسي لكتابة الجملة الأخيرة.","最初[さいしょ]は প্রথম প্রস্তাব চিহ্নিত করছে; এটি চূড়ান্ত সমাধান নয়।":"最初[さいしょ]は يحدد الاقتراح الأول؛ ليس الحل النهائي.","প্রথমে নির্দেশনার কাগজ বাড়ানোর কথা ভাবা হলো।":"في البداية، فكروا في زيادة أوراق التعليمات.","এই অভিজ্ঞতার মাধ্যমে মিনা কথার পাশাপাশি পরিস্থিতিও যাচাই করতে শুরু করল।":"من خلال هذه التجربة، بدأت مينا التحقق من الموقف إلى جانب المحادثة.","কারণ লক্ষ্যগোষ্ঠী কেবল একটি ক্লাস।":"لأن الجمهور المستهدف هو فصل واحد فقط.","১২ জন ট্রেন, ৫ জন সাইকেল এবং ৩ জন হেঁটে যাওয়ার কথা বলল।":"12 شخصا قالوا القطار، و5 قالوا الدراجة، و3 قالوا المشي.","かのように উপমা; বাস্তবে সব কথা মুছে গেছে এমন তথ্য নয়।":"かのように تشبيه؛ ليس حقيقة أن كل الكلمات مُحيت فعلا.","聞[き]きました-র প্রশ্নবিষয় দিয়ে পরের উত্তরের কেন্দ্র নির্ধারিত হয়।":"موضوع السؤال في 聞[き]きました يحدد تركيز الإجابة التالية.","ট্রেন ব্যবহারকারীর অনুপাত ৬০ শতাংশ।":"نسبة مستخدمي القطار هي 60 بالمئة.","তাই কর্মীরা পরিচিত ভাষায় লেখা নির্দেশনা ব্যবহার করলেন।":"لذلك، استخدم الموظفون تعليمات مكتوبة بلغة مألوفة.","এখানে 難[むずか]しい কেবল কাজের জটিলতা নাও বোঝাতে পারে।":"هنا، 難[むずか]しい قد لا يعني ببساطة تعقيد العمل.","を通[とお]して অভিজ্ঞতার মাধ্যমে শেখা; ようになった আচরণের পরিবর্তন।":"を通[とお]して هو التعلم من خلال التجربة؛ ようになった هو تغير في السلوك.","に応[おう]じて মানিয়ে নেওয়া; そうです বক্তার কাছ থেকে শোনা তথ্য।":"に応[おう]じて هو التكيف؛ そうです هو معلومات سُمعت من شخص آخر.","たとたん পৌঁছানোর সঙ্গে হঠাৎ উপলব্ধি বোঝায়।":"たとたん يوحي بإدراك مفاجئ عند الوصول.","গ্রাহকের চাহিদা অনুযায়ী তিনি ব্যাখ্যার ক্রম ও ভাষা বদলান।":"يغير ترتيب الشروح واللغة وفقا لاحتياجات العميل.","ことなく মানে না করে; মিনার আগেই খবর না দেওয়া এখানে গুরুত্বপূর্ণ।":"ことなく يعني دون فعل؛ عدم إشعار مينا مسبقا مهم هنا.","কেন এক বন্ধুকে পরদিন বাসা বদলে সাহায্য করতে বলল।":"لماذا طلب صديق من آخر مساعدته في الانتقال في اليوم التالي.","শেষ বাক্য প্রতিবেদকের উপলব্ধি; ম্যানেজারের সরাসরি উদ্ধৃতি নয়।":"الجملة الأخيرة هي إدراك المراسل، وليست اقتباسا مباشرا من المدير.","মনে হলো, মন দিয়ে অন্যের কথা শোনাই আস্থার শুরু।":"شعرت أن الاستماع بانتباه إلى الآخرين هو بداية الثقة.","শেষ প্রতিক্রিয়া থেকে স্বস্তি ও আনন্দ বোঝা যায়।":"رد الفعل الأخير ينقل الارتياح والفرح.","প্রথম বাক্যে বলা তথ্যটি আমন্ত্রণের ভাষা; এখনো সময় নির্দিষ্ট হয়নি।":"المعلومات المذكورة في الجملة الأولى هي لغة الدعوة؛ لم يُحدد الوقت بعد.","কিন্তু ব্যবহারকারীদের সঙ্গে কথা বলে জানা গেল, শ্রেণিবিভাগের নাম বোঝা কঠিন।":"لكن بعد التحدث مع المستخدمين، وُجد أن أسماء التصنيفات صعبة الفهم.","ইউ প্রতিদিন ব্যবহার করা খাতাটি ট্রেনে ফেলে এল।":"تركت يوي دفترها اليومي في القطار.","だけでは十分[じゅうぶん]ではない সীমা দেখাচ্ছে; কোনো ব্যাখ্যাই প্রয়োজন নেই বলা হয়নি।":"だけでは十分[じゅうぶん]ではない يظهر حدا؛ لا يقول إنه لا حاجة لأي شرح على الإطلاق.","এই পরিস্থিতিতে “কঠিন” কথাটি পরদিনের অনুরোধ প্রত্যাখ্যান করছে।":"في هذا الموقف، كلمة «صعب» هي رفض لطلب اليوم التالي.","অর্থ বুঝতে শব্দের পাশাপাশি প্রসঙ্গও জরুরি।":"لفهم المعنى، السياق مهم بقدر الكلمات.","そこで আগের তথ্যের ভিত্তিতে করা পদক্ষেপকে যুক্ত করছে।":"そこで يربط الإجراء المتخذ بناء على المعلومات السابقة.","মিনাকে এক বন্ধু বলল, “আবার বেড়াতে এসো।”":"قال صديق لمينا: «تعالي للزيارة مرة أخرى.»","にすぎない পরিসরের সীমাবদ্ধতা দেখায়।":"にすぎない يظهر محدودية النطاق.","একটি লাইব্রেরিতে বই খুঁজতে বেশি সময় লাগে বলে মতামত এসেছিল।":"وُردت ملاحظات بأن العثور على الكتب في مكتبة يستغرق وقتا طويلا.","শুরুতে ব্যবহারকারীর সমস্যা তুলে ধরা হয়েছে।":"في البداية، تُبرز مشكلة المستخدم.","১২÷২০×১০০=৬০; শুধু সংখ্যা নয়, মোটের ভিত্তি দেখুন।":"12÷20×100=60؛ انظر إلى أساس المجموع، لا الأرقام فقط.","তবে শুধু এই ফল দিয়ে জাপানের সব শিক্ষার্থী সম্পর্কে বলা যায় না।":"لكن من هذه النتيجة وحدها، لا يمكن القول عن جميع الطلاب في اليابان.","যেমন, প্রথমবার আসা ব্যক্তিকে ব্যবহারের পদ্ধতি দিয়ে বোঝানো শুরু করেন।":"على سبيل المثال، للزائر لأول مرة، يبدأ الشرح بإظهار كيفية الاستخدام."},"study.reading_title":{"“একটু কঠিন” কথাটির পর কী হলো":"«صعب قليلا» — ما حدث بعد تلك الكلمات","সমস্যার বদলে প্রয়োজন থেকে ভাবা":"التفكير من الاحتياجات بدلا من المشاكل","ভালো সেবা মানে একই উত্তর নয়":"الخدمة الجيدة لا تعني الإجابة نفسها","একটি আমন্ত্রণ, দুই রকম ধারণা":"دعوة واحدة ونوعان من الانطباعات","হারানো খাতার ছোট গল্প":"قصة قصيرة عن دفتر مفقود","জরিপের সংখ্যা থেকে কতটুকু বলা যায়":"كم يمكن أن يُقال من أرقام الاستطلاع"},"study.strategy":{"শব্দের আক্ষরিক অর্থের পাশাপাশি কে, কাকে, কোন অনুরোধে বলছে তা দেখুন। পরোক্ষ কথাকে সবার জন্য স্থির নিয়ম হিসেবে ধরবেন না।":"إلى جانب المعنى الحرفي للكلمات، انظر إلى من يتحدث، ولمن، وبأي طلب. لا تعامل الكلام غير المباشر كقاعدة ثابتة للجميع.","শিরোনাম ও ছোট উপশিরোনাম দেখে যুক্তির ধাপ ধরুন। দাবি, কারণ, উদাহরণ ও বিকল্পকে আলাদা করুন। মতের বিরোধিতা করলে কারণসহ বিকল্প দিন।":"تتبع خطوات الحجة بالنظر إلى العنوان والعناوين الفرعية. افصل الادعاءات والأسباب والأمثلة والبدائل. وإذا عارضت رأيا، قدّم بديلا مع الأسباب.","চরিত্রের অনুভূতি কোন ঘটনা বা শব্দে বদলেছে তা দেখুন। উপমাকে বাস্তব ঘটনা হিসেবে নেবেন না। পর্যালোচনায় নিজের মূল্যায়নের কারণ দিন।":"انظر إلى الأحداث أو الكلمات التي غيّرت مشاعر الشخصيات. لا تأخذ الاستعارات كأحداث فعلية. قدّم أسباب تقييماتك في المراجعة.","প্রশ্নের উত্তরে বক্তা প্রথমে সিদ্ধান্ত বলেছেন, না উদাহরণ দিয়েছেন, তা ধরুন। উদাহরণ কোন মূল কথাকে বোঝাচ্ছে সেটি খুঁজুন।":"التقط ما إذا كان المتحدث ذكر قراره أولا أم أعطى أمثلة ردا على أسئلة. اعثر على النقطة الرئيسية التي توضحها الأمثلة.","বাক্যে কর্তা বাদ গেলে আগের বাক্য ও কথোপকথনের প্রবাহ দেখুন। অনুমান আর স্পষ্টভাবে বলা তথ্য আলাদা রাখুন।":"إذا كان الفاعل مفقودا في جملة، انظر إلى تدفق الجملة السابقة والمحادثة. حافظ على فصل الافتراضات عن المعلومات المذكورة صراحة.","জরিপের লক্ষ্যগোষ্ঠী, মোট উত্তরদাতা, সময় ও শতাংশের ভিত্তি আগে পড়ুন। উদাহরণের সংখ্যাকে বাস্তব জরিপের ফল হিসেবে ব্যবহার করবেন না।":"اقرأ المجموعة المستهدفة للاستطلاع وإجمالي المستجيبين والوقت وأساس النسبة المئوية أولا. لا تستخدم أرقام الأمثلة كنتائج استطلاع حقيقية."},"study.vocab":{"প্রকাশভঙ্গি":"التعبير","দৃষ্টিকোণ":"وجهة النظر","ভুল বোঝাবুঝি":"سوء الفهم","অনুভূতি":"المشاعر","আস্থা":"الثقة","উদ্বেগ":"القلق","অভিজ্ঞতা":"التجربة","লক্ষ্যগোষ্ঠী বা বিষয়":"المجموعة أو الموضوع المستهدف","জরিপ বা অনুসন্ধান":"الاستطلاع أو البحث","অনুপাত":"النسبة","উদ্দেশ্য":"الغرض","অন্যের কথা বিবেচনা":"مراعاة الآخرين","প্রসঙ্গ":"السياق","ভূমিকা":"المقدمة","সংকোচ বা সংযম":"التردد أو ضبط النفس","চিন্তার সূচনা বা ধারণা":"بداية التفكير أو المفهوم","পারস্পরিক আদানপ্রদান":"التبادل المتبادل","কৌশল বা বুদ্ধিদীপ্ত চেষ্টা":"الاستراتيجية أو الجهد الذكي","সহযোগিতা":"التعاون","চাহিদা বা আশা":"الطلب أو التوقع","ভিন্ন সংস্কৃতি":"ثقافة مختلفة","প্রস্তাব":"الاقتراح","অভ্যাস বা রীতি":"العادة أو التقليد","স্বস্তি":"الارتياح","গ্রাহকসেবা":"خدمة العملاء","হ্রাস":"النقصان","মনের ওপর ছাপ":"الانطباع على الذهن","বৃদ্ধি":"الزيادة","তুলনা":"المقارنة","গল্প বা আখ্যান":"القصة أو السرد","দৃশ্য বা পরিস্থিতি":"المشهد أو الموقف","যাচাই করা":"التحقق","প্রত্যাখ্যান করা":"الرفض","উন্নতি":"التحسين","জানানো":"الإبلاغ"},"study.writing":{"আমি খাতা হারানো একজনের ছোট গল্প পড়েছি।":"قرأت قصة قصيرة عن شخص فقد دفتره.","ট্রেন ব্যবহারকারী ১২ জন, যা সবচেয়ে বড় অংশ।":"مستخدمو القطار 12 شخصا، وهي الشريحة الأكبر.","কিন্তু বন্ধু ভেবেছিল এখনো আলোচনা দরকার।":"لكن الصديق ظن أن النقاش ما زال ضروريا.","আমারও প্রিয় জিনিস হারানোর অভিজ্ঞতা আছে বলে অনুভূতিটি বুঝেছি।":"فهمت الشعور لأن لدي أيضا تجربة فقدان شيء مفضل.","অনুশীলনের জরিপে একটি ক্লাসের ২০ শিক্ষার্থীকে প্রশ্ন করা হয়েছে।":"في استطلاع التدريب، سُئل 20 طالبا من فصل واحد.","এই অভিজ্ঞতার পর গুরুত্বপূর্ণ বিষয় স্পষ্টভাবে বলে নিশ্চিত করার চেষ্টা করি।":"بعد هذه التجربة، أحاول ذكر الأمور المهمة بوضوح والتأكد منها.","মূল চরিত্রের উদ্বেগ পরিচিত ভাষায় তুলে ধরা হয়েছে।":"قلق الشخصية الرئيسية معبَّر عنه بلغة مألوفة.","যেমন কঠিন শব্দ পরিচিত প্রকাশে বদলে দেওয়া যায়।":"على سبيل المثال، يمكن تغيير الكلمات الصعبة إلى تعبيرات مألوفة.","তাই যারা ব্যবহার করবেন তাঁদের মতামত শোনা উচিত বলে মনে করি।":"لذلك، أظن أننا يجب أن نستمع إلى آراء من سيستخدمونه.","এটি এমন গল্প যা দৈনন্দিন ছোট ঘটনাকেও গুরুত্ব দিতে শেখায়।":"هذه قصة تعلمنا تقدير حتى الأحداث اليومية الصغيرة.","আমি ভেবেছিলাম সময় ঠিক হয়ে গেছে।":"ظننت أن الوقت قد حُسم.","সম্পর্ক ও পরিস্থিতি অনুযায়ী তা বদলায়।":"يتغير وفقا للعلاقة والموقف.","আমার মতে নির্দেশনা তৈরির সময় ব্যবহারকারীর দৃষ্টিকোণ জরুরি।":"في رأيي، وجهة نظر المستخدم أساسية عند إنشاء التعليمات.","দীর্ঘ অভিজ্ঞতার ভিত্তিতে তিনি বোঝানোর ধরনে কৌশল ব্যবহার করেন।":"بناء على خبرته الطويلة، يستخدم تقنيات استراتيجية في طريقة شرحه.","তাঁর মতে সবচেয়ে গুরুত্বপূর্ণ হলো গ্রাহকের কথা শোনা।":"وفقا له، أهم شيء هو الاستماع إلى العميل.","আমি পাশের দোকানের ম্যানেজারের সাক্ষাৎকার নিয়েছি।":"أجريت مقابلة مع مدير المتجر المجاور.","জাপানিতে কোনো সময় না করার আগে কারণ বলা হয়।":"في اليابانية، يُذكر سبب قبل الرفض.","না বুঝলে আমি ভদ্রভাবে নিশ্চিত হতে চাই।":"إذا لم أفهم، أريد التأكد بأدب.","আমিও অন্যের অবস্থান বিবেচনা করে কাজ করতে চাই বলে মনে হয়েছে।":"شعرت أنني أنا أيضا أريد التصرف مع مراعاة وجهات نظر الآخرين.","তবে সবসময় একই প্রকাশ ব্যবহার হয় না।":"لكن التعبير نفسه تماما لا يُستخدم دائما.","জাপানে নতুন আসার সময় এক বন্ধুর সঙ্গে কথা দেওয়া নিয়ে সমস্যায় পড়েছিলাম।":"عندما جئت إلى اليابان لأول مرة، واجهت مشكلة في إعطاء وعد لصديق.","সাইকেল ব্যবহারকারীর তুলনায় ৭ জন বেশি।":"7 أشخاص أكثر مقارنة بمستخدمي الدراجات.","কারণ তথ্য বেশি হলেই অর্থ পরিষ্কার হয় এমন নয়।":"لأن مزيدا من المعلومات لا يعني بالضرورة أن المعنى أوضح.","তবে অল্পসংখ্যক ব্যক্তির ফল বলে এটি সামগ্রিক প্রবণতা নাও হতে পারে।":"لكن بما أن النتائج لعدد صغير من الأشخاص، فقد لا تكون اتجاها عاما."},"study.writing_prompt":{"নিজের একটি ভুল বোঝাবুঝির অভিজ্ঞতা লিখুন: ঘটনা → নিজের ধারণা → অন্য পক্ষের অবস্থা → পরেরবার কী করবেন।":"اكتب عن تجربة سوء فهم خاصة بك: الحدث ← افتراضك ← موقف الطرف الآخر ← ما ستفعله في المرة القادمة.","বাংলা ও জাপানিতে কোনো অনুরোধ ফিরিয়ে দেওয়ার একটি করে উদাহরণ দিন। শব্দের অর্থ, সম্পর্ক ও পরিস্থিতি আলাদা করে লিখুন; জাতিগত সাধারণীকরণ এড়িয়ে চলুন।":"أعط مثالا واحدا لكل من رفض طلب بالبنغالية وباليابانية. اكتب معاني الكلمات والعلاقات والمواقف بشكل منفصل؛ وتجنب التعميمات العرقية.","একটি গল্প বা সিনেমার সংক্ষিপ্ত রিভিউ লিখুন: পরিচয় → একটি দৃশ্য → নিজের অনুভূতি → সুপারিশের কারণ। সমাপ্তির সব তথ্য বলে দেবেন না।":"اكتب مراجعة قصيرة لقصة أو فيلم: مقدمة ← مشهد ← مشاعرك ← سبب التوصية. لا تكشف كل معلومات النهاية.","এই কাল্পনিক সংখ্যাগুলো ব্যবহার করে চার বাক্যের প্রতিবেদন লিখুন। লক্ষ্যগোষ্ঠী → সবচেয়ে বড় অংশ → তুলনা → সিদ্ধান্তের সীমা।":"اكتب تقريرا من أربع جمل باستخدام هذه الأرقام الافتراضية. الجمهور المستهدف ← الشريحة الأكبر ← مقارنة ← حد الاستنتاج.","একটি ছোট সমস্যা বেছে ১৮০–২৫০ জাপানি অক্ষরে মতামত লিখুন: দাবি → কারণ → উদাহরণ → সম্ভাব্য আপত্তি → বাস্তব প্রস্তাব।":"اختر مشكلة صغيرة واكتب رأيا في 180-250 حرفا يابانيا: ادعاء ← سبب ← مثال ← اعتراض محتمل ← اقتراح عملي.","কোনো পরিচিত ব্যক্তির কাজ সম্পর্কে তিনটি প্রশ্ন করুন। সরাসরি উক্তি এবং নিজের উপলব্ধি আলাদা করে একটি ছোট প্রতিবেদন লিখুন।":"اسأل ثلاثة أسئلة عن عمل شخص تعرفه. اكتب تقريرا قصيرا يفصل الاقتباسات المباشرة عن إدراكاتك الخاصة."},"title":{"QUARTET II · বাংলা গ্রামার সহায়িকা":"QUARTET II · دليل القواعد"}},"qa":{"attr.aside@aria-label":{"পাঠ নির্বাচন":"اختيار الدرس"},"attr.div@aria-label":{"পড়ার ধরন":"أسلوب القراءة"},"attr.input@aria-label":{"গ্রামার খুঁজুন":"ابحث في القواعد"},"attr.meta@description":{"QUARTET Ⅱ-এর অধ্যায় ৭–১২-এর থিমে নির্বাচিত ৩৬টি বিষয়ে নিজস্ব বাংলা ব্যাখ্যা, ফুরিগানাসহ উদাহরণ ও অনুশীলন।":"شروح بنغالية أصلية، وأمثلة مع فوريغانا، وتمارين تدريبية حول 36 موضوعا مختارا بناء على موضوعات الفصول 7-12 من QUARTET Ⅱ."},"attr.nav@aria-label":{"এই অধ্যায়ের গ্রামার":"قواعد هذا الفصل","QUARTET বই ও পড়ার ধরন":"كتب QUARTET وأنواع القراءة","পথ নির্দেশনা":"التنقل"},"attr.progress@aria-label":{"গ্রামার শেখার অগ্রগতি":"تقدم تعلم القواعد"},"text.uncovered":{"পাঠ ও অনুশীলন খুলতে JavaScript চালু করুন।":"فعّل JavaScript لفتح الدروس والتدريب.","N2 Grammar পড়ুন":"اقرأ قواعد N2"}}};
